from functools import lru_cache

@lru_cache(None)
def F(n):
    if n == 1:
        return 1
    return n * F(n - 1)

for i in range(1, 3039):          # прогрев: F(1), F(2), … по порядку — глубина рекурсии 1–2
    F(i)
print((F(3038) + 5 * F(3037)) // F(3036))

def F(n):
    if n >= 2025:
        return n
    return n + F(n + 2)

