from functools import lru_cache

@lru_cache(None)
def g(n):
    if n <= 20:
        return n + 2
    return g(n - 3) + 1

def f(n):
    return 3 * g(n - 3) + 7

for i in range(0, 37811):          # прогрев вместо setrecursionlimit
    g(i)
print(f(37811))

from functools import lru_cache

@lru_cache(None)
def F(n):
    return n if n < 5 else 2 * n * F(n - 4)

for i in range(2, 13767, 4):        # нужны только аргументы с остатком 2 при делении на 4
    F(i)
print((F(13766) - 9 * F(13762)) // F(13758))

from functools import lru_cache
from math import comb

@lru_cache(None)
def F(n):
    if n == 0:
        return 1
    return 1 + F(n - 1) if n % 2 else F(n // 2)

assert all(F(n) == 1 + bin(n).count('1') for n in range(1, 10000))  # проверка малых n, не вывод ответа
print(comb(29, 2))                       # 2^28 + 2^27 < 500 000 000 < 2^29: подходят все пары 29 позиций

k = 0
def F(n):
    global k
    k += 1                          # считаем вызовы — без кэша!
    if n < 2:
        return 1
    return F(n - 1) + F(n - 2)

