from functools import lru_cache

@lru_cache(None)
def F(n):
    if n < 3:
        return 1
    if n % 2:
        return F(n - 1) + n
    return F(n - 3) + 2 * n

print(F(20))

from functools import lru_cache

@lru_cache(None)
def F(n):
    if n < 10:
        return n
    return F(n // 10) + n % 10        # сумма цифр числа

print(sum(1 for n in range(1, 10000) if F(n) == 9))
